let issues: any[] = [];
for (let page = 1; page <= 50; page++) {
  const r = norm(await tools.list_issues({ repo, state: "open", label: "bug", page }));
  if (r.length === 0) break;
  issues.push(...r);
}

const sample = issues[0] ? Object.keys(issues[0]) : [];
const hasAssignee = (i: any) => {
  if (i.assignee) return true;
  if (Array.isArray(i.assignees) && i.assignees.length > 0) return true;
  return false;
};
const unassigned = issues.filter(i => !hasAssignee(i) && i.pull_request == null);

const results: any[] = [];
