      const c = norm(await tools.list_comments({ repo, number: i.number, page }));
      n += c.length;
      if (c.length < 50) break;
    }
    count = n;
  }
  results.push({ number: i.number, comments: count, hasLabelBug: true });
}

const matching = results.filter(r => r.comments > 5);
return {
  totalOpenBug: issues.length,
  unassignedNonPR: unassigned.length,
  sampleKeys: sample,
  matchingCount: matching.length,
  matching: matching.map(m => m.number),
  allCounts: results.map(r => [r.number, r.comments]),
};
